%[text]{"align":"center"} $\\frac{dT}{dt} = \\alpha \\frac{d^2T}{dx^2}$
% Discretize the domain
n = 20;
x = linspace(0,0.1,n)';
dx = x(2) - x(1);
dt = 0.000001;
alpha = 100;
r = alpha*dt/dx^2  %[output:945ab39c]
%%

% Create the initial condition
T = 0*x; % degC

% Apply boundary condition
T(1) = 0;
T(end) = 20;
plot(x,T) %[output:55111766]

%[text] T(0) = 0 and T(1) = 20
%[text]{"align":"center"} $\\frac{T\_{i+1}-T\_{i} }{\\Delta t} = \\alpha \\frac{d^2T\_{i+1}}{dx^2} \\quad (1)\n\n$
%[text]{"align":"center"} 
%[text]{"align":"center"} $T\_{i+1}-T\_{i}   =  \\Delta t\\times \\alpha \\frac{d^2T\_{i+1}}{dx^2}$
%[text]{"align":"center"} $T\_{i+1}  - T\_i  =  \\Delta t\\times \\alpha \\frac{d^2T\_{i+1}}{dx^2} \\\\\n\nT\_{i+1}  - T\_i  = \\Delta t \\times \\alpha \\times A \\times T\_{i+1}\\\\\n\n(1 - \\Delta t \\times \\alpha \\times A)T\_{i+1} = T\_i\\\\\n\nM\\times T\_{i+1} = T\_i\\\\\n\nM = (1 - \\Delta t \\times \\alpha \\times A)\\\\\n\n\n$
% Find a way to compute \Delta T
A = zeros(n) %[output:84438e23]
for ii = 2:n-1
    A(ii,ii) = -2/dx^2;
    A(ii,ii-1) = 1/dx^2;
    A(ii,ii+1) = 1/dx^2;
end
A %[output:05a2ac8e]
M = (eye(n) - dt*alpha*A) %[output:8a06199b]
%[text] T\_i+1(1) = T\_i(1)
%[text] T\_i+1(end) = T\_i(end)
%%

for nt = 1:1000
    % update T
    T = M\T;

    % Apply boundary condition
    T(1) = 0;
    T(end) = 20;
end

hold on %[output:6708eb03]
plot(x,T) %[output:6708eb03]
hold off %[output:6708eb03]
%%
%[text]{"align":"center"} $r = \\alpha \\frac{\\Delta t}{\\Delta x^2}$

